TASKS = [
    ("math_proof", {"complexity": 5, "latency_sensitive": False}),
    ("chat_widget", {"complexity": 2, "latency_sensitive": True}),
    ("report_draft", {"complexity": 3, "latency_sensitive": False}),
]

def route(task):
    if task["complexity"] >= 4:
        return "o-series"
    if task["latency_sensitive"] is True:
        return "gpt-mini"
    return "gpt-flagship"

for name, task in TASKS:
    print(f"{name} -> {route(task)}")
print(f"routed={len(TASKS)}")
